package app.rafiq.personal;
import android.app.Activity;
import android.os.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import android.text.InputType;
import com.google.android.gms.wearable.*;
import org.json.*;
import java.util.UUID;

public class WatchActivity extends Activity implements DataClient.OnDataChangedListener {
 JSONObject plan=new JSONObject();int selected=0,tab=0;LinearLayout layout;TextView status,timer,pulse,pulseState;EditText weight,reps;CountDownTimer countdown;WatchSensors sensors;long lastSend=0;
 final int GREEN=Color.rgb(255,149,74),BLUE=Color.rgb(255,189,142),PURPLE=Color.rgb(224,224,224),BG=Color.rgb(11,11,11),MUTED=Color.rgb(170,170,170);
 int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 @Override public void onCreate(Bundle state){super.onCreate(state);try{plan=new JSONObject(getPreferences(0).getString("plan","{}"));}catch(Exception ignored){}sensors=new WatchSensors(this,new WatchSensors.Callback(){public void state(String text){if(pulseState!=null)pulseState.setText(text);}public void reading(float bpm,int accuracy){if(pulse!=null)pulse.setText(String.valueOf(Math.round(bpm)));if(pulseState!=null)pulseState.setText("نبضة/د · من حساس الساعة الآن");long now=System.currentTimeMillis();if(now-lastSend>=10000){lastSend=now;try{send(new JSONObject().put("type","heart").put("bpm",bpm).put("accuracy",accuracy),false);}catch(Exception ignored){}}}});render();}
 @Override public void onResume(){super.onResume();Wearable.getDataClient(this).addListener(this);Wearable.getDataClient(this).getDataItems().addOnSuccessListener(items->{try{for(DataItem item:items)read(item);}finally{items.release();}});}
 @Override public void onPause(){sensors.stop();getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);Wearable.getDataClient(this).removeListener(this);super.onPause();}
 void read(DataItem item){if(!"/rafiq/plan".equals(item.getUri().getPath()))return;try{JSONObject next=new JSONObject(DataMapItem.fromDataItem(item).getDataMap().getString("json"));boolean changed=!next.optString("sessionId").equals(plan.optString("sessionId"));plan=next;getPreferences(0).edit().putString("plan",plan.toString()).apply();if(changed)selected=0;runOnUiThread(()->{if(tab==0||changed)render();});}catch(Exception ignored){}}
 @Override public void onDataChanged(DataEventBuffer events){for(DataEvent e:events)if(e.getType()==DataEvent.TYPE_CHANGED)read(e.getDataItem());}
 TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER);t.setFontFeatureSettings("tnum");t.setPadding(0,dp(3),0,dp(3));layout.addView(t);return t;}
 Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setTextSize(12);b.setAllCaps(false);b.setTextColor(GREEN);b.setBackground(bg(Color.rgb(41,30,22),24));b.setOnClickListener(v->action.run());LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(44));lp.setMargins(0,dp(7),0,dp(3));layout.addView(b,lp);return b;}
 EditText number(String label,double value){text(label,10,MUTED);EditText e=new EditText(this);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);e.setText(String.valueOf(value));e.setTextColor(Color.WHITE);e.setTextSize(23);e.setGravity(Gravity.CENTER);e.setBackground(bg(Color.rgb(30,30,30),14));layout.addView(e,new LinearLayout.LayoutParams(-1,dp(48)));return e;}
 void render(){pulse=null;pulseState=null;ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(BG);layout=new LinearLayout(this);layout.setOrientation(LinearLayout.VERTICAL);layout.setPadding(dp(20),dp(18),dp(20),dp(32));scroll.addView(layout);setContentView(scroll);text("رَفِيق / PERFORMANCE",9,GREEN);
 LinearLayout tabs=new LinearLayout(this);for(int i=0;i<3;i++){final int destination=i;Button b=new Button(this);b.setText(new String[]{"يومي","تمرين","نبض"}[i]);b.setTextSize(10);b.setAllCaps(false);b.setTextColor(i==tab?BG:MUTED);b.setBackground(bg(i==tab?GREEN:Color.rgb(29,29,29),20));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(28),1);lp.setMargins(dp(2),dp(5),dp(2),dp(3));tabs.addView(b,lp);b.setOnClickListener(v->{if(destination!=tab){sensors.stop();getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}tab=destination;render();});}layout.addView(tabs);
 if(tab==0)home();else if(tab==1)workout();else heart();
 status=text("المزامنة مع موبايلك عند الاتصال",9,MUTED);button("فحص تحديث التطبيق",this::checkUpdate);try{text("v"+getPackageManager().getPackageInfo(getPackageName(),0).versionName,9,MUTED);}catch(Exception ignored){}
 }
 void home(){float readiness=(float)plan.optDouble("readiness",-1),sleep=(float)plan.optDouble("sleepPercent",0),food=plan.optInt("goal",0)>0?plan.optInt("kcal",0)*100f/plan.optInt("goal",1):0;layout.addView(new VitalRings(this,readiness,sleep,food),new LinearLayout.LayoutParams(-1,dp(108)));text(readiness<0?"نبني خطك الأساسي":"جاهزية تقديرية من رفيق",10,GREEN);text("النوم "+(plan.has("sleepHours")?plan.optString("sleepHours")+" س":"—")+"  ·  HRV "+(plan.has("hrv")?plan.optString("hrv"):"—"),11,PURPLE);text(plan.optString("name","افتح رفيق على الموبايل"),17,Color.WHITE);button("افتح جلسة التمرين",()->{tab=1;render();});text("الغذاء "+plan.optInt("kcal",0)+" / "+plan.optInt("goal",0)+" سعرة",11,MUTED);text("الماي "+plan.optInt("water",0)+" مل",12,BLUE);button("+ 250 مل ماي",()->{try{send(new JSONObject().put("type","water").put("ml",250),true);}catch(Exception ignored){}});text("الدوائر: جاهزية · نوم · غذاء",9,MUTED);}
 void workout(){JSONArray exercises=plan.optJSONArray("exercises");if(exercises==null||exercises.length()==0){text("افتح تمرينك بالموبايل حتى توصل الخطة",13,MUTED);return;}selected=Math.min(selected,exercises.length()-1);JSONObject ex=exercises.optJSONObject(selected);text(plan.optString("name")+"  /  "+(selected+1)+" من "+exercises.length(),10,GREEN);text(ex.optString("name"),19,Color.WHITE);text(ex.optString("sets")+" × "+ex.optString("reps")+" · "+ex.optString("unit"),11,MUTED);weight=number("الوزن",storedNumber("weight-"+ex.optString("id"),ex.optDouble("weight",0)));reps=number("التكرارات",storedNumber("reps-"+ex.optString("id"),10));button("✓ سجّل الجولة",()->{try{double w=Double.parseDouble(weight.getText().toString()),r=Double.parseDouble(reps.getText().toString());if(!Double.isFinite(w)||w<0||w>2000||r<1||r>300||r!=Math.floor(r)){status.setText("راجع الأوزان والتكرارات");return;}JSONObject event=new JSONObject().put("type","set").put("sessionId",plan.getString("sessionId")).put("exerciseId",ex.getString("id")).put("name",ex.getString("name")).put("unit",ex.getString("unit")).put("basis",ex.getString("basis")).put("weight",w).put("reps",r);send(event,true);getPreferences(0).edit().putString("weight-"+ex.optString("id"),String.valueOf(w)).putString("reps-"+ex.optString("id"),String.valueOf(r)).apply();startRest(ex.optInt("rest",90));}catch(Exception e){status.setText("أدخل أرقاماً صحيحة");}});timer=text("مؤقت الراحة",25,PURPLE);button("ابدأ راحة",()->startRest(ex.optInt("rest",90)));button("التمرين التالي ←",()->{selected=(selected+1)%exercises.length();render();});button("→ التمرين السابق",()->{selected=(selected+exercises.length()-1)%exercises.length();render();});}
 double storedNumber(String key,double fallback){try{return Double.parseDouble(getPreferences(0).getString(key,String.valueOf(fallback)));}catch(Exception e){return fallback;}}
 void heart(){text("نبضك، هسه.",21,Color.WHITE);pulse=text("—",58,Color.rgb(251,142,133));pulse.setTypeface(Typeface.create("sans-serif-light",0));pulseState=text("قراءة مباشرة باختيارك",11,MUTED);button("بدء قياس النبض",()->{getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);sensors.start();});button("إيقاف القياس",()->{sensors.stop();getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);pulse.setText("—");pulseState.setText("توقف القياس");});text("القياس أثناء فتح الشاشة فقط. تنحفظ قراءة كل 10 ثوانٍ للمزامنة. لا نقيس HRV من معدل النبض.",10,MUTED);}
 @Override public void onRequestPermissionsResult(int requestCode,String[] permissions,int[] results){super.onRequestPermissionsResult(requestCode,permissions,results);if(requestCode==41){if(results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)sensors.start();else if(pulseState!=null)pulseState.setText("صلاحية النبض مطلوبة لبدء القياس");}}
 void checkUpdate(){status.setText("نفحص التحديث…");new Thread(()->{try{String installed=getPackageManager().getPackageInfo(getPackageName(),0).versionName;JSONObject result=UpdateCheck.check(installed,"Rafiq-watch.apk");runOnUiThread(()->{if(result.optBoolean("available"))new android.app.AlertDialog.Builder(this).setTitle("تحديث "+result.optString("version")).setMessage("نزّل Rafiq-watch.apk من صفحة إصدارات رفيق وثبّته عبر ADB اللاسلكي. لا تحذف التطبيق الحالي.").setPositiveButton("تمام",null).show();else status.setText("عندك أحدث إصدار ✓");});}catch(Exception e){runOnUiThread(()->status.setText("تعذر الفحص؛ تأكد من الإنترنت"));}}).start();}
 void send(JSONObject event,boolean feedback)throws JSONException{String id=UUID.randomUUID().toString();event.put("id",id).put("time",java.time.Instant.now().toString());PutDataMapRequest map=PutDataMapRequest.create("/rafiq/event/"+id);map.getDataMap().putString("json",event.toString());Wearable.getDataClient(this).putDataItem(map.asPutDataRequest().setUrgent()).addOnSuccessListener(x->{if(feedback){status.setText("انحفظ للمزامنة ✓");vibrate();}}).addOnFailureListener(e->{if(status!=null)status.setText("تعذرت المزامنة؛ جرّب مرة ثانية");});}
 void startRest(int seconds){if(countdown!=null)countdown.cancel();countdown=new CountDownTimer(Math.max(1,seconds)*1000L,1000){public void onTick(long n){if(timer!=null)timer.setText((n/60000)+":"+String.format(java.util.Locale.US,"%02d",(n/1000)%60));}public void onFinish(){if(timer!=null)timer.setText("جاهز للجولة؟");vibrate();}}.start();}
 void vibrate(){android.os.Vibrator v=(android.os.Vibrator)getSystemService(VIBRATOR_SERVICE);if(v!=null)v.vibrate(VibrationEffect.createOneShot(100,VibrationEffect.DEFAULT_AMPLITUDE));}
 @Override public void onDestroy(){sensors.stop();if(countdown!=null)countdown.cancel();super.onDestroy();}
}
